INSERT INTO team_match_stats VALUES(16284981,'AVL','2026-08-07',0.5300000000000000266,1.320000000000000062,8,16,3,8,1,1,336,461,NULL,14,NULL,30,NULL,1,3,7,61.0,9,18,'4-4-2','4-2-3-1','sofascore / [2026-08-15 프리시즌 보강] FotMob /api/data/matchDetails + /api/data/teams (실제 Chrome 경유 수집 2026-08-15) / [2026-08-16 정정] formation_v를 FotMob away formation으로 보정','measured / measured / ⚠️ 원천은 SofaScore가 아니라 **FotMob**이다 — 같은 테이블의 기존 SofaScore 행과 provenance가 다르다. ⛔ **xG는 FotMob이 친선에 제공하지 않는다**(스탯 그룹 자체에 없음) — 이 행들의 xg_v/xg_o는 NULL이며 0이 아니다. ⛔ **PPDA도 산출 불가** — WhoScored가 클럽 친선을 커버하지 않아(픽스처 44건 전부 공식전) Opta 이벤트 원천이 없다. / ⚠️ **[2026-08-16 정정] formation_v가 비어 있었다.** 08-15 수집 때 빌라 포메이션을 "어느 출처도 적지 않았다"고 판단했으나 FotMob matchDetails 5449690이 **away formation = 4-4-2**로 제공하고 있었다(home=바이에른 4-2-3-1). 선수 positionId 배열(11 / 32·34·36·38 / 72·74·76·78 / 104·106)도 4-4-2와 정합한다. ⚠️ 다만 로더가 pos_of()에 넘긴 formation 인자는 홈팀 값(4-2-3-1)이었는데, 두 값 모두 백4라 **lineup_pos 산출 결과에는 영향이 없다**(백3일 때만 분기한다).',NULL,NULL,NULL,NULL,NULL,NULL,NULL,7,11,4,11,5,17,3,25,30,22,3,6,16,17);
