INSERT INTO team_match_stats VALUES(16846122,'LIV','2026-08-16',NULL,NULL,10,14,2,4,3,1,376,540,37,17,38,25,18,4,4,8,58.0,10,9,'4-2-3-1','4-2-3-1','SofaScore /event/16846122/statistics (period ALL, 수집 2026-08-17)','measured — SofaScore /event/16846122/statistics (period ALL, 수집 2026-08-17). ⚠️ xG는 소스가 0.00으로 주는데 이는 실제 0이 아니라 **친선에 xG 모델 미적용**이다 → NULL로 적재. ppda는 미수집(이벤트 단위 패스-액션 원자료 없음).',NULL,NULL,NULL,NULL,NULL,NULL,NULL,6,13,7,13,12,15,7,20,22,12,4,10,19,16);
INSERT INTO team_match_stats VALUES(5868012,'ATM','2026-08-19',0.9200000000000000399,0.1499999999999999945,15,5,6,1,3,0,520,467,50,28,59,23,15,5,6,1,48.60000000000000142,17,11,'4-1-4-1','4-1-4-1','FotMob matchDetails+heatmap matchId=5868012 (26/27 LaLiga R1 · Atletico 2-0 Malaga · 2026-08-19T19:05Z · 응답 내 coach="Diego Simeone") — 좌표는 heatmap 엔드포인트의 <circle cx cy> (105×68 피치) → 소파 규약 환산(sx=cx/105*100, sy=cy/68*100) ; PPDA·포메이션: WhoScored matchCentreData(Opta) matchId=1993898 https://www.whoscored.com/matches/1993898/live/spain-laliga-2026-2027-atletico-madrid-malaga','[2026-08-20] ⚠️ **원천이 SofaScore가 아니라 FotMob이다** — 이 회차에 SofaScore가 사이트 전역 403이라 런북의 대체 경로를 썼다. ⭐ **좌표 방위를 실증으로 검증했다**: 오블락(GK) 평균 cx=13(낮음) ⇒ 자기 골문이 cx=0이고 공격 방향이 +cx · 다니 마르티네스(RB) 평균 cy=9.1 ↔ 카를로스 마르틴(LB) cy=55.0 ⇒ **낮은 cy=우측**으로 소파 규약(y 낮음=오른쪽)과 일치. 그리드도 이 방위로 재검증했다(오블락은 자기 골문·중앙, 다니는 col4, 마르틴은 col0). ⚠️ 격자 계산식은 `core.sofascore.js_collect`의 __grid와 동일하다(row=4-floor(sx/20), col=floor((100-sy)/20)). ⭐ **xG가 존재한다**(0.92 vs 0.15) — 런북의 「xG는 대체 경로에 없다」는 **클럽 친선 한정**이고 공식전(라리가)에서는 FotMob이 제공한다. xGOT 2.64 vs 0.02. ⚠️ long_att·cross_att는 「28 (56%)」식 표기에서 역산했다(28/0.56=50, 5/0.33=15) — 반올림 오차가 있다. ⛔ **PPDA는 산출하지 않았다** — Opta 이벤트 원천(WhoScored)에 접근하지 못했다(실제 Chrome 미연결). | [2026-08-20] ⭐⭐ **PPDA 산출 완료 — ATM 7.77 vs 말라가 11.46.** 낮을수록 압박이 강하다 ⇒ **아틀레티코가 훨씬 강하게 압박했다**(수비 액션 44 대 28). 점유 53%·상대 진영 패스 266과 합쳐, 이 경기의 아틀레티코는 **저블록이 아니라 전방 압박 + 점유** 쪽이었다. docs/13의 「하이브리드 이동」 문헌 진단과 정합. ⚠️⚠️ **포메이션을 5-4-1 → 4-1-4-1로 정정**했다 — FotMob은 5-4-1로 읽었으나 Opta formations 배열은 **4141(0~61분) → 442(61~96분)**이고, Opta의 명시적 포지션 라벨(DL/DR/ML/MR)이 선수별로 검증된다. 말라가도 4141이다. ⚠️ PPDA 구역 정의는 문헌마다 다르다 — 여기 쓴 정의를 ppda_method에 명기했다.',7.769999999999999574,11.46000000000000086,342,44,321,28,'압박 팀의 수비 액션(Tackle+Interception+Challenge+Foul)이 상대 진영 60% 구역(압박 팀 기준 x≥40)에서 일어난 건수를 분모로, 같은 구역에서 상대가 시도한 패스(상대 기준 x≤60)를 분자로 계산. Opta 이벤트 1,606건 기준.',12,18,6,18,8,22,10,22,20,21,9,13,13,23);
INSERT INTO team_match_stats VALUES(5795369,'AVL','2026-08-23',0.3099999999999999978,3.669999999999999929,6,21,0,6,0,6,240,642,37,13,53,44,4,1,2,5,47.89999999999999858,9,12,'4-2-3-1','4-2-3-1','FotMob matchDetails matchId=5795369 (curl, 2026-08-24 수집) — 팀·선수 스탯·평점·분·샷맵 xG / WhoScored matchCentreData(Opta) matchId=1983554 이벤트 1452건 (인앱 브라우저 오리진 fetch) — 좌표·평균위치·5x5 그리드·PPDA·듀얼/드리블 원천. ⛔ SofaScore 미사용(obs#290 egress IP 엣지 차단).','measured. ⭐ **xG가 실측으로 존재한다**(0.31 vs 3.67) — 런북의 「WhoScored·FotMob 모두 xG 미제공」은 **클럽 친선 한정**이고 PL 공식전에서는 FotMob이 팀·슛 단위 xG를 모두 준다(ATM 08-19 선례와 동일). 슛 단위 xG 합 0.307이 팀 표시값 0.31과 일치해 자체 정합 확인. ⚠️ long_att·cross_att·aerial_att·dribble_att는 「13 (35%)」식 표기에서 역산했다(13/0.35=37 등) — 반올림 오차 ±1. ⚠️⚠️ **PPDA 24.69는 정의상 유효하지만 해석에 두 교란이 있다**: ① 40분 João Gomes 퇴장으로 50분간 10명이었다 ② 점유율 27%로 상대 진영 체류 시간 자체가 짧았다. 압박 「의도」의 지표로 단독 사용하지 말 것. 직전 실측(슈퍼컵 08-12 AVL 12.59)과의 Δ12.1은 체제 변화가 아니라 경기 국면 산물일 수 있다. ⚠️ PPDA 정의는 슈퍼컵 행(16260286)과 동일하게 맞췄다 — 다른 산출사 PPDA와 직접 비교 금지(obs#79).',24.69000000000000127,5.200000000000000177,395,16,208,40,'분자=상대가 자기 진영 3/5(x<60)에서 시도한 패스 · 분모=해당 팀 수비액션(Tackle·Interception·Challenge·Foul) 상대 진영 2/5(x>40). 원천=WhoScored matchCentreData(Opta) 이벤트 1452건, 2026-08-24 수집. ⚠️ PPDA는 구현마다 존 경계·액션 종류가 다르다 — 이 정의와 다른 출처의 PPDA를 직접 비교하지 말 것.',7,24,17,24,7,14,4,8,20,21,8,10,23,12);
INSERT INTO team_match_stats VALUES(5795371,'LIV','2026-08-23',2.979999999999999983,1.580000000000000071,27,13,7,4,3,3,445,296,46,22,54,15,27,7,6,2,51.5,15,16,'4-2-3-1','4-2-3-1','FotMob matchDetails matchId=5795371 (curl, 2026-08-24 수집) — 팀·선수 스탯·평점·분·xG·물리량 / WhoScored matchCentreData(Opta) matchId=1983547 이벤트 1412건 (인앱 브라우저) — 좌표·평균위치·5x5 그리드·PPDA / Liverpool FC 공식 리포트·Sky Sports·Guardian·AS·Cadena SER·El País (2026-08-23~24).','measured. 경기 종료 약 5시간 뒤 초판이라 지연 전술 영상·전문 블로그는 미반영. D+1~D+3 재검색 전까지 match report는 draft.',5.950000000000000177,8.550000000000000711,256,43,265,31,'분자=상대가 자기 진영 3/5(x<60)에서 시도한 패스 · 분모=해당 팀 수비액션(Tackle·Interception·Challenge·Foul) 상대 진영 2/5(x>40). 원천=WhoScored/Opta 이벤트 1412건.',13,24,11,24,5,13,4,14,17,19,8,4,18,39);
